// A failure that is someone else's ceiling is not a defect of ours. The status vocabulary
// separates them: blocked = an external limit, error = our fault.
const e = $json.execution || {};
const msg = String((e.error && e.error.message) || 'unknown');
const node = e.lastNodeExecuted || null;
const external = /rate.?limit|429|quota|too many requests|daily limit|insufficient balance|payment required|402|503|502|504|timeout|ETIMEDOUT|ECONNRESET/i;
return [{ json: {
  n8n_execution_id: String(e.id == null ? '' : e.id),
  status: external.test(msg) ? 'blocked' : 'error',
  stage: 'failed',
  error_node: node,
  error_message: msg.slice(0, 1000),
  finished_at: new Date().toISOString()
} }];
